-- 075_saved_dive_itineraries.sql
-- Stores persisted user dive plans generated by SINSAY AI Dive Assistant
-- with full JSON structure and user ownership RLS.

create table if not exists public.saved_dive_itineraries (
  id uuid default gen_random_uuid() primary key,
  tourist_id uuid not null references public.tourists(id) on delete cascade,
  title text not null,
  budget text,
  group_size integer,
  activity text,
  length_of_stay text,
  plan_data jsonb not null,
  created_at timestamptz default now()
);

alter table public.saved_dive_itineraries enable row level security;

create policy "Insert own saved itineraries"
  on public.saved_dive_itineraries for insert
  with check (auth.uid() = tourist_id);

create policy "Read own saved itineraries"
  on public.saved_dive_itineraries for select
  using (auth.uid() = tourist_id);

create policy "Delete own saved itineraries"
  on public.saved_dive_itineraries for delete
  using (auth.uid() = tourist_id);
